draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var th = p.angle * Math.PI / 180;
var F = p.force, d = 6.0;
var Wk = F * d * Math.cos(th);

function arw(x1, y1, x2, y2, col, lw) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = lw;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1), hl = 8;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - hl * Math.cos(a - 0.4), y2 - hl * Math.sin(a - 0.4));
  ctx.lineTo(x2 - hl * Math.cos(a + 0.4), y2 - hl * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
}

var gy = H * 0.70;
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(W * 0.04, gy); ctx.lineTo(W * 0.96, gy); ctx.stroke();

var bw = W * 0.11, bh = H * 0.15;
var bx = W * 0.20;
ctx.strokeStyle = C.ink; ctx.lineWidth = 1.5;
ctx.strokeRect(bx, gy - bh, bw, bh);
ctx.fillStyle = C.ink;
ctx.fillText("sled", bx + bw * 0.18, gy - bh * 0.35);

var ox = bx + bw, oy = gy - bh;
var scale = W * 0.0042;
var ex = ox + F * scale * Math.cos(th);
var ey = oy - F * scale * Math.sin(th);
arw(ox, oy, ex, ey, C.accent, 2);
ctx.fillStyle = C.accent;
ctx.fillText("F = " + F.toFixed(0) + " N", ex + 6, ey - 2);

var cx = ox + F * scale * Math.cos(th);
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(ex, ey); ctx.lineTo(cx, oy); ctx.stroke();
ctx.setLineDash([]);
arw(ox, oy, cx, oy, C.figure, 2);
ctx.fillStyle = C.figure;
ctx.fillText("F cos" + "θ = " + (F * Math.cos(th)).toFixed(1) + " N", ox + 4, oy - 8);

ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.arc(ox, oy, 26, -th, 0); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("θ = " + p.angle.toFixed(0) + "°", ox + 30, oy - 26 * Math.sin(th / 2) - 4);

var ay = gy + H * 0.14;
arw(bx, ay, bx + W * 0.45, ay, C.rule, 1.5);
ctx.fillStyle = C.ink;
ctx.fillText("d = 6.0 m", bx + W * 0.16, ay + 15);

ctx.fillStyle = C.faint;
ctx.fillText("only the shaded-out horizontal part travels with the sled", W * 0.04, H * 0.13);

out.note = "W = F d cosθ = " + F.toFixed(0) + " × 6.0 × " + Math.cos(th).toFixed(3) + " = " + Wk.toFixed(1) + " J";
